  "analysis": "The heredoc is still having issues with newlines in strings. Let me try a different approach - I'll write the Python code to a file using printf with proper escaping, or use a simpler inline Python approach.",
  "plan": "Use printf to write the Python script to a file, then execute it. This should avoid the heredoc issues.",
  "commands": [
    {
      "keystrokes": "printf '%s\\n' '#!/usr/bin/env python3' 'import json' 'from pathlib import Path' '' 'TOKENGUARD_DIR = Path(\".tokenguard\")' 'LIMIT_FILE = TOKENGUARD_DIR / \"limit.json\"' 'SESSION_FILE = TOKENGUARD_DIR / \"session.json\"' '' 'def load_json_file(filepath):' '    if not filepath.exists():' '        return None' '    with open(filepath, \"r\") as f:' '        return json.load(f)' '' 'limit_data = load_json_file(LIMIT_FILE)' 'session_data = load_json_file(SESSION_FILE)' '' 'if session_data is None:' '    summary = {' '        \"has_session\": False,' '        \"message\": \"No TokenGuard session data found\",' '        \"current_limit\": None,' '        \"total_spent\": None,' '        \"remaining_budget\": None,' '        \"warning_threshold\": None,' '        \"num_entries\": 0,' '        \"top_entries\": []' '    }' '    report = \"TOKENGUARD SESSION SUMMARY REPORT\\\\n\"' '    report += \"No session data found.\"' 'else:' '    current_limit = limit_data.get(\"limit\", 0) if limit_data else 0' '    currency = limit_data.get(\"currency\", \"USD\") if limit_data else \"USD\"' '    warning_pct = limit_data.get(\"warning_pct\", 0.8) if limit_data else 0.8' '    warning_threshold = current_limit * warning_pct' '    total_spent = session_data.get(\"spent\", 0)' '    remaining_budget = current_limit - total_spent' '    entries = session_data.get(\"entries\", [])' '    num_entries = len(entries)' '    sorted_entries = sorted(entries, key=lambda x: x.get(\"amount\", 0), reverse=True)' '    top_entries = sorted_entries[:3]' '    summary = {' '        \"has_session\": True,' '        \"current_limit\": current_limit,' '        \"currency\": currency,' '        \"total_spent\": total_spent,' '        \"remaining_budget\": remaining_budget,' '        \"warning_threshold\": warning_threshold,' '        \"warning_percentage\": int(warning_pct * 100),' '        \"num_entries\": num_entries,' '        \"top_entries\": [{\"amount\": e.get(\"amount\"), \"description\": e.get(\"desc\"), \"timestamp\": e.get(\"ts\")} for e in top_entries]' '    }' '    lines = [' '        \"=\" * 80,' '        \"                    TOKENGUARD SESSION SUMMARY REPORT\",' '        \"=\" * 80,' '        \"\",' '        \"BUDGET OVERVIEW\",' '        \"-\" * 20,' '        f\"Current Limit:       \\${current_limit:.2f} {currency}\",' '        f\"Total Spent:         \\${total_spent:.2f}\",' '        f\"Remaining Budget:    \\${remaining_budget:.2f}\",' '        f\"Warning Threshold:   \\${warning_threshold:.2f} ({int(warning_pct * 100)}%)\",' '        f\"Status:              {'WARNING' if total_spent >= warning_threshold else 'OK'}\",' '        \"\",' '        \"LOG ENTRIES\",' '        \"-\" * 14,' '        f\"Total Entries:       {num_entries}\",' '        \"\",' '        \"TOP 3 MOST EXPENSIVE ENTRIES\",' '        \"-\" * 31,' '    ]' '    for i, entry in enumerate(top_entries, 1):' '        amount = entry.get(\"amount\", 0)' '        desc = entry.get(\"desc\", \"No description\")' '        ts = entry.get(\"ts\", \"Unknown\")' '        lines.append(f\"   {i}. \\${amount:.2f} - {desc}\")' '        lines.append(f\"      (at {ts})\")' '        lines.append(\"\")' '    if not top_entries:' '        lines.append(\"   No entries logged yet.\")' '        lines.append(\"\")' '    lines.append(\"=\" * 80)' '    lines.append(\"                              END OF REPORT\")' '    lines.append(\"=\" * 80)' '    report = \"\\\\n\".join(lines)' '' 'with open(\"tokenguard_summary.txt\", \"w\") as f:' '    f.write(report)' 'print(\"Generated: tokenguard_summary.txt\")' '' 'with open(\"tokenguard_summary.json\", \"w\") as f:' '    json.dump(summary, f, indent=2)' 'print(\"Generated: tokenguard_summary.json\")' > generate_tokenguard_summary.py\\n",
      "duration": 0.5
    },
